BEGIN;

UPDATE public.grammar_exercises
SET question_de = 'Welche Präposition nennt einen Grund?'
WHERE id = 'd2e403ec-a185-4fc1-a728-d7ddb877fd30'::uuid
  AND question_de = 'Which preposition means "because of"?';

UPDATE public.grammar_exercises
SET question_en = 'Which preposition gives a reason? (options: trotz / wegen / während / statt)'
WHERE id = 'd2e403ec-a185-4fc1-a728-d7ddb877fd30'::uuid
  AND question_en = 'Welche Präposition bedeutet "wegen"?';

UPDATE public.grammar_exercises
SET explanation_de = 'wegen nennt einen Grund. trotz nennt ein Hindernis. während nennt eine Zeit. statt nennt eine Alternative.'
WHERE id = 'd2e403ec-a185-4fc1-a728-d7ddb877fd30'::uuid
  AND explanation_de = 'wegen = weil. während = während. trotz = obwohl. statt = anstatt.';

UPDATE public.grammar_exercises
SET question_de = 'Welches Relativpronomen zeigt Besitz bei einem femininen Nomen?'
WHERE id = '86a85535-d844-4c99-b322-fe99c337ea7e'::uuid
  AND question_de = 'Which relative pronoun means "whose" for feminine nouns?';

UPDATE public.grammar_exercises
SET question_en = 'Which relative pronoun shows possession with a feminine noun?'
WHERE id = '86a85535-d844-4c99-b322-fe99c337ea7e'::uuid
  AND question_en = 'Welches Relativpronomen bedeutet "deren" für feminine Nomen?';

UPDATE public.grammar_exercises
SET explanation_de = 'deren zeigt Besitz bei femininen Nomen und im Plural. dessen zeigt Besitz bei maskulinen und neutralen Nomen.'
WHERE id = '86a85535-d844-4c99-b322-fe99c337ea7e'::uuid
  AND explanation_de = 'deren = deren für feminin/plural. dessen = dessen für maskulin/neutral.';

COMMIT;
